<?php
require_once __DIR__.'/../_shared/admin-auth.php';
bp_cors('GET, OPTIONS');$id=(int)($_GET['admin_id']??0);$a=bp_admin($id);if(!$a){http_response_code(403);echo json_encode(['status'=>'error','message'=>'Admin access required.']);exit;}$role=strtolower($a['role']);$c=bp_admin_conn();
if($role==='student_admin'){$r=$c->query('SELECT COUNT(*) total_students,SUM(account_status="active") active_students,SUM(account_status="deactivated") deactivated_students FROM student WHERE date_deleted IS NULL');$summary=$r->fetch_assoc();$r=$c->query('SELECT st.strand_name,COUNT(*) total FROM student s LEFT JOIN strand st ON st.strand_id=s.strand_id WHERE s.date_deleted IS NULL GROUP BY st.strand_name ORDER BY total DESC');$byStrand=[];while($x=$r->fetch_assoc())$byStrand[]=$x;echo json_encode(['status'=>'success','role'=>$role,'summary'=>$summary,'by_strand'=>$byStrand]);}
elseif($role==='content_admin'){$s=$c->prepare('SELECT COUNT(*) total, SUM(approval_status="pending") pending, SUM(approval_status="approved") approved, SUM(approval_status="rejected") rejected FROM learning_material WHERE admin_id=? AND date_deleted IS NULL');$s->bind_param('i',$id);$s->execute();$m=$s->get_result()->fetch_assoc();$s->close();$s=$c->prepare('SELECT COUNT(*) total, SUM(approval_status="pending") pending, SUM(approval_status="approved") approved, SUM(approval_status="rejected") rejected FROM quiz WHERE admin_id=?');$s->bind_param('i',$id);$s->execute();$q=$s->get_result()->fetch_assoc();$s->close();echo json_encode(['status'=>'success','role'=>$role,'learning_materials'=>$m,'quizzes'=>$q]);}
else{$r=$c->query('SELECT (SELECT COUNT(*) FROM student WHERE date_deleted IS NULL) total_students,(SELECT COUNT(*) FROM admin WHERE date_deleted IS NULL) total_admins,(SELECT COUNT(*) FROM subject WHERE date_deleted IS NULL) total_subjects,(SELECT COUNT(*) FROM quiz) total_quizzes,(SELECT COUNT(*) FROM learning_material WHERE date_deleted IS NULL) total_materials,(SELECT COUNT(*) FROM quiz WHERE approval_status="pending") pending_quizzes,(SELECT COUNT(*) FROM learning_material WHERE date_deleted IS NULL AND approval_status="pending") pending_materials');echo json_encode(['status'=>'success','role'=>'super_admin','summary'=>$r->fetch_assoc()]);}$c->close();
